func (a *Handler) handleDeltaReport(ctx context.Context, rw http.ResponseWriter, filteredSccs []*nsmodel.SCC, details *[]httputil.Detail, _ nsmodel.Report) {
	a.processDelta(ctx, filteredSccs, details)
	if len(*details) == 0 {
		httputils.RespondWithBody(ctx, rw, http.StatusNoContent, struct{}{})
		return
	}

	httputil.RespondWithError(ctx, rw, http.StatusOK, httputil.DetailedError{
		Code:    http.StatusOK,
		Message: "Update/create failed for some on-premise systems",
		Details: *details,
	})
}

func (a *Handler) handleFullReport(ctx context.Context, rw http.ResponseWriter, filteredSccs []*nsmodel.SCC, details *[]httputil.Detail, reportData nsmodel.Report) {
	a.processDelta(ctx, filteredSccs, details)
	a.handleUnreachableScc(ctx, reportData)
	httputils.RespondWithBody(ctx, rw, http.StatusNoContent, struct{}{})
}

